func (t Tags) getGainValue(tagName, r128TagName string) float64 {
	// Gain is in the form [-]a.bb dB
	tag := t.getFirstTagValue(tagName)
	if tag == "" {
		// Try R128 tag
		tag = t.getFirstTagValue(r128TagName)
		if tag == "" {
			return 0
		}
		// R128 gain is in Q7.8 format, and the reference is -23 LUFS, while ReplayGain is -18 LUFS
		value, err := strconv.ParseFloat(tag, 64)
		if err != nil || math.IsInf(value, 0) || math.IsNaN(value) {
			return 0
		}
		return value/256 + 5
	}
	tag = strings.TrimSpace(strings.Replace(tag, "dB", "", 1))
	value, err := strconv.ParseFloat(tag, 64)
	if err != nil || math.IsInf(value, 0) || math.IsNaN(value) {
		return 0
	}
	return value
}

